   /**
    * Creates the provided command.
    * 
    * @param		command ${class.getCreateCommandAlias()}
    * @exception    ProcessingException
    * @exception	IllegalArgumentException
    * @return		DataTask
    */
	public DataTask createDataTask( CreateDataTaskCommand command )
    throws ProcessingException, IllegalArgumentException {

		DataTask entity = new DataTask();

		try {
			// --------------------------------------
        	// validate the command
        	// --------------------------------------    	
        	DataTaskValidator.getInstance().validate( command );    

            entity.setDataTaskId( command.getDataTaskId() );
            entity.setName( command.getName() );
            entity.setCommand( command.getCommand() );
            entity.setRetries( command.getRetries() );
            entity.setTaskType( command.getTaskType() );
    	    
        	// ------------------------------------------
        	// persist a new one
        	// ------------------------------------------ 
    	    entity = projector.create(entity);
    	    
			LOGGER.log( Level.INFO, "done creating of DataTask {0} ", entity.toString() );
			
        }
        catch (Exception exc) {
            final String errMsg = "Unable to create DataTask - " + exc;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }

