            entity.setRetries( command.getRetries() );
            entity.setPipeline( command.getPipeline() );
            entity.setInputDatasets( command.getInputDatasets() );
            entity.setOutputDatasets( command.getOutputDatasets() );
            entity.setTaskType( command.getTaskType() );
        	
        	// ------------------------------------------
        	// persist an existing one
