    /**
     * Method to retrieve the DataTask via DataTaskFetchOneSummary
     * @param 	summary DataTaskFetchOneSummary 
     * @return 	DataTaskFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public DataTask getDataTask( DataTaskFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "DataTaskFetchOneSummary arg cannot be null" );
    	
    	DataTask entity = null;
    	UUID id = summary.getDataTaskId();
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	DataTaskValidator.getInstance().validate( summary );    
        	
        	// --------------------------------------
        	// find a DataTask using the provided id
        	// --------------------------------------
        	entity = projector.find( id );
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate DataTask with id " + id;
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


