    /**
     * assign Pipeline on DataTask
     * @param		command AssignPipelineToDataTaskCommand	
     * @exception	ProcessingException
     */     
	public void assignPipeline( AssignPipelineToDataTaskCommand command ) throws ProcessingException {

		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	DataTaskValidator.getInstance().validate( command );    

			// --------------------------------------
	    	// delegate to the projector
	    	// --------------------------------------    	    	
	    	projector.assignPipeline(command.getDataTaskId(), command.getAssignment());
		    
		}
        catch( Throwable exc ) {
			final String msg = "Failed to get DataPipeline using id " + command.getDataTaskId();
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

